import { z } from "zod";

/**
 * The contract between `apps/web` and `apps/api`: shared zod schemas and the
 * types inferred from them. This skeleton (ticket 01) holds the status state
 * machines (D16), the pipeline limits (D17), a shared error-response shape, and
 * the health-check payload used by the walking skeleton. Later tickets extend
 * it with the run, evaluation, posting and SSE event shapes.
 */

/**
 * Run status machine (D16): discovering → evaluating → applying → completed | failed.
 * Transitions only move forward; one function will own transitions in a later ticket.
 */
export const runStatusSchema = z.enum([
  "discovering",
  "evaluating",
  "applying",
  "completed",
  "failed",
]);
export type RunStatus = z.infer<typeof runStatusSchema>;

/**
 * Evaluation (per-job) status machine (D16):
 * queued → evaluating → blocked | skipped | held | applying → submitted | failed.
 * `submitted` is a simulated submit (D18). Each status carries a reason elsewhere.
 */
export const evaluationStatusSchema = z.enum([
  "queued",
  "evaluating",
  "blocked",
  "skipped",
  "held",
  "applying",
  "submitted",
  "failed",
]);
export type EvaluationStatus = z.infer<typeof evaluationStatusSchema>;

/** Pipeline limits (D17): at most 3 jobs in flight and 15 AI evaluations per run. */
export const MAX_IN_FLIGHT = 3;
export const MAX_AI_EVALS = 15;
export const LIMITS = {
  maxInFlight: MAX_IN_FLIGHT,
  maxAiEvals: MAX_AI_EVALS,
} as const;

/**
 * The single JSON error shape every API route returns on failure — never a
 * stack trace (CODING_STANDARDS, API section).
 */
export const errorResponseSchema = z.object({
  error: z.object({
    code: z.string(),
    message: z.string(),
  }),
});
export type ErrorResponse = z.infer<typeof errorResponseSchema>;

/**
 * Which `Repo` implementation the API is running on. `memory` is only ever
 * chosen explicitly and loses everything on restart (ADR-0004).
 */
export const repoKindSchema = z.enum(["firestore", "memory"]);
export type RepoKind = z.infer<typeof repoKindSchema>;

/**
 * Health-check payload (`GET /api/health`). It names the active repository and
 * namespace so an in-memory demo is never mistaken for a persistent one
 * (ADR-0004).
 */
export const healthResponseSchema = z.object({
  status: z.literal("ok"),
  service: z.string(),
  namespace: z.string(),
  repo: repoKindSchema,
  time: z.string(),
});
export type HealthResponse = z.infer<typeof healthResponseSchema>;

/* -------------------------------------------------------------------------- *
 * Firestore documents (D14) and the identities built from them.
 *
 * These shapes travel to the browser over SSE as run and evaluation snapshots
 * (D21), so they live in the contract. Product-rich fields — the rubric inside
 * preferences (D6), the per-criterion evidence and built Greenhouse payload on
 * an Evaluation (D7, D18) — are owned by later tickets; this ticket fixes
 * identity, status and funnel, enough for the persistence port and its tests.
 * -------------------------------------------------------------------------- */

/** The ATS boards discovery reads from (D2). */
export const atsSchema = z.enum(["greenhouse", "lever", "ashby"]);
export type Ats = z.infer<typeof atsSchema>;

/**
 * A single job as returned by an ATS board, normalised into our own shape
 * (GLOSSARY: Posting). The unit of discovery.
 */
export const postingSchema = z.object({
  ats: atsSchema,
  board: z.string(),
  jobId: z.string(),
  title: z.string(),
  company: z.string(),
  location: z.string(),
  descriptionText: z.string(),
  applyUrl: z.string().url(),
});
export type Posting = z.infer<typeof postingSchema>;

/**
 * The stable identity of a Posting across the several URLs an ATS exposes for
 * it (GLOSSARY: Job Key, D14): `${ats}:${board}:${jobId}`. It is both the
 * Evaluation document id (within its Run) and the Seen key.
 */
export function jobKey(posting: Pick<Posting, "ats" | "board" | "jobId">): string {
  return `${posting.ats}:${posting.board}:${posting.jobId}`;
}

/**
 * The single user document (D13): profile, the preferences rubric (D6) and
 * settings. The detailed shapes of these three are owned by later tickets, so
 * here they are open records — the persistence port and its tests do not pin
 * down product fields yet.
 */
export const userDocSchema = z.object({
  uid: z.string(),
  profile: z.record(z.string(), z.unknown()),
  preferences: z.record(z.string(), z.unknown()),
  settings: z.record(z.string(), z.unknown()),
});
export type UserDoc = z.infer<typeof userDocSchema>;

/**
 * Per-run funnel counts (D16). They are only ever incremented, never
 * read-modify-written (CODING_STANDARDS landmine: lost updates); the Firestore
 * adapter maps increments to `FieldValue.increment`.
 */
export const runFunnelSchema = z.object({
  discovered: z.number().int().nonnegative(),
  evaluated: z.number().int().nonnegative(),
  blocked: z.number().int().nonnegative(),
  skipped: z.number().int().nonnegative(),
  held: z.number().int().nonnegative(),
  submitted: z.number().int().nonnegative(),
  failed: z.number().int().nonnegative(),
});
export type RunFunnel = z.infer<typeof runFunnelSchema>;

/** A fresh, all-zero funnel for a newly created Run. */
export function emptyFunnel(): RunFunnel {
  return { discovered: 0, evaluated: 0, blocked: 0, skipped: 0, held: 0, submitted: 0, failed: 0 };
}

/**
 * One unattended pass of the pipeline (GLOSSARY: Run). `reason` is set when a
 * run ends `failed` (D16); timestamps are ISO-8601 strings.
 */
export const runSchema = z.object({
  runId: z.string(),
  uid: z.string(),
  status: runStatusSchema,
  funnel: runFunnelSchema,
  reason: z.string().nullable(),
  createdAt: z.string(),
  updatedAt: z.string(),
});
export type Run = z.infer<typeof runSchema>;

/**
 * A Run is active until it reaches a terminal status. This drives the
 * one-active-run-per-user rule (D17) that `createRun` enforces as a future 409.
 */
export function isRunActive(status: RunStatus): boolean {
  return status !== "completed" && status !== "failed";
}

/** The outcome the rubric assigns a Posting (GLOSSARY: Verdict, D8). */
export const verdictSchema = z.enum(["APPLY_NOW", "APPLY", "STRETCH", "BLOCKED"]);
export type Verdict = z.infer<typeof verdictSchema>;

/**
 * The per-run record of what we decided about one Posting (GLOSSARY:
 * Evaluation), stored as one document under its Run. Per-criterion evidence and
 * the built Greenhouse payload are added by the scoring and submit tickets.
 */
export const evaluationSchema = z.object({
  jobKey: z.string(),
  runId: z.string(),
  posting: postingSchema,
  status: evaluationStatusSchema,
  verdict: verdictSchema.nullable(),
  score: z.number().nullable(),
  reason: z.string().nullable(),
  createdAt: z.string(),
  updatedAt: z.string(),
});
export type Evaluation = z.infer<typeof evaluationSchema>;
/**
 * The persistence port the whole backend depends on — never `firebase-admin`
 * directly (CLAUDE.md, Persistence port). Two implementations satisfy it: the
 * Firestore adapter and an in-memory twin with the same subscription behaviour.
 * A single shared contract suite exercises both so they cannot drift.
 *
 * This is a backend-only port: the browser never sees a `Repo` (it talks HTTP
 * and SSE). The document shapes it moves — {@link Run}, {@link Evaluation} and
 * friends — live in `contract.ts` because those *do* travel to the browser.
 */
import type {
  Evaluation,
  EvaluationStatus,
  Run,
  RunFunnel,
  RunStatus,
  UserDoc,
  Verdict,
} from "./contract.js";

/** Returned by every `watch*` call; stops delivery and releases the listener. */
export type Unsubscribe = () => void;

/**
 * Receives what a subscription cannot deliver (ADR-0003): a stored document
 * that fails contract validation (skipped; the subscription keeps going) or a
 * listener failure in the backend (the subscription ends). Never silent — the
 * SSE stream turns it into an error event.
 */
export type SubscriptionErrorHandler = (error: Error) => void;

/**
 * A forward-only patch to a Run. `funnelIncrements` are *added* to the current
 * counts — never an overwrite — so the Firestore adapter can map them to
 * `FieldValue.increment` (CODING_STANDARDS landmine: lost updates). `updatedAt`
 * is set by the adapter, not the caller.
 */
export interface RunDelta {
  status?: RunStatus;
  reason?: string | null;
  funnelIncrements?: Partial<RunFunnel>;
}

/** A patch to a single Evaluation. `updatedAt` is set by the adapter. */
export interface EvaluationDelta {
  status?: EvaluationStatus;
  verdict?: Verdict | null;
  score?: number | null;
  reason?: string | null;
}

/** Mirrors a Firestore collection change: how an Evaluation entered the stream. */
export type ChangeType = "added" | "modified" | "removed";

export interface EvaluationChange {
  type: ChangeType;
  evaluation: Evaluation;
}

/**
 * Thrown by `createRun` when the user already has an active Run. The route maps
 * it to `409` — one active run per user (D17). Carries the offending run id so
 * callers and logs can name it.
 */
export class ActiveRunExistsError extends Error {
  constructor(
    readonly uid: string,
    readonly activeRunId: string,
  ) {
    super(`user ${uid} already has an active run (${activeRunId})`);
    this.name = "ActiveRunExistsError";
  }
}

/**
 * The persistence contract. Writes echo back to live subscribers; each `watch*`
 * is state-based (ADR-0003): an initial snapshot asynchronously (never
 * synchronously), then callbacks for later matching writes, in write order.
 * Like Firestore's `onSnapshot`, a backend may coalesce rapid writes into one
 * callback, but it never delivers a stale state after a newer one and the last
 * callback always reflects the latest write — so consumers render the latest
 * state and never count callbacks. Errors go to `onError`.
 */
export interface Repo {
  getUser(uid: string): Promise<UserDoc | null>;
  /** Seeds the user on first boot (D13); a no-op if the document already exists. */
  seedUserIfMissing(uid: string, doc: UserDoc): Promise<void>;

  /** Creates a Run; rejects with {@link ActiveRunExistsError} if one is active (D17). */
  createRun(run: Run): Promise<void>;
  getActiveRun(uid: string): Promise<Run | null>;
  patchRun(runId: string, delta: RunDelta): Promise<void>;

  putEvaluation(runId: string, evaluation: Evaluation): Promise<void>;
  patchEvaluation(runId: string, jobKey: string, delta: EvaluationDelta): Promise<void>;

  /** Seen spans Runs so dedupe survives across them (GLOSSARY: Seen, D15). */
  isSeen(jobKey: string): Promise<boolean>;
  markSeen(jobKey: string): Promise<void>;

  watchRun(runId: string, cb: (run: Run) => void, onError: SubscriptionErrorHandler): Unsubscribe;
  watchEvaluations(
    runId: string,
    cb: (change: EvaluationChange) => void,
    onError: SubscriptionErrorHandler,
  ): Unsubscribe;
}
export * from "./contract.js";
export * from "./repo.js";
import express, { type Request, type Response, type NextFunction } from "express";
import cors from "cors";
import {
  errorResponseSchema,
  healthResponseSchema,
  type HealthResponse,
} from "@auto-apply/shared";
import type { Config } from "./config.js";
import type { Persistence } from "./repo/create-repo.js";
import { logger } from "./logger.js";

/**
 * Builds the Express app. Kept separate from `index.ts` so tests can drive it
 * with Supertest without opening a socket. Routes stay thin: later tickets add
 * the run routes and the SSE stream here.
 */
export function createApp(config: Config, persistence: Persistence) {
  const app = express();

  // Behind nginx in production (CLAUDE.md, Deployment).
  app.set("trust proxy", 1);

  // Permissive dev CORS so web (5173) can call api (3001). Tightened to an
  // exact origin with credentials in ticket 15 (D27).
  app.use(cors());

  app.use(express.json({ limit: "100kb" }));

  app.get("/api/health", (_req: Request, res: Response) => {
    const body: HealthResponse = {
      status: "ok",
      service: "auto-apply-api",
      namespace: config.FIRESTORE_NAMESPACE,
      repo: persistence.kind,
      time: new Date().toISOString(),
    };
    res.json(healthResponseSchema.parse(body));
  });

  // Unknown routes get the shared JSON error shape, not Express's HTML default.
  app.use((_req: Request, res: Response) => {
    res.status(404).json(
      errorResponseSchema.parse({
        error: { code: "not_found", message: "Not found" },
      }),
    );
  });

  // Errors return the shared JSON shape, never a stack trace (CODING_STANDARDS).
  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    logger.error("unhandled_error", {
      error: err instanceof Error ? err.message : String(err),
    });
    res.status(500).json(
      errorResponseSchema.parse({
        error: { code: "internal", message: "Internal server error" },
      }),
    );
  });

  return app;
}
import { loadConfig } from "./config.js";
import { createApp } from "./app.js";
import { logger } from "./logger.js";
import { createRepo } from "./repo/create-repo.js";

// Env and the Firestore credential are both validated here, once; anything
// invalid stops the boot. The run routes use `persistence.repo` from ticket 05.
const config = loadConfig();
const persistence = createRepo(config);
const app = createApp(config, persistence);

if (persistence.kind === "memory") {
  logger.warn("persistence_in_memory", { reason: "REPO=memory; data is lost on restart" });
}

app.listen(config.PORT, () => {
  logger.info("api_listening", {
    port: config.PORT,
    namespace: config.FIRESTORE_NAMESPACE,
    persistence: persistence.kind,
  });
});
import { z } from "zod";
import { repoKindSchema } from "@auto-apply/shared";

/** An env var that may be absent or blank; blank counts as unset. */
const optionalString = z
  .string()
  .optional()
  .transform((value) => (value ? value : undefined));

/**
 * Environment is parsed once, at startup, and the process fails fast if it is
 * invalid (CODING_STANDARDS, General). Later tickets add the auth, CORS and AI
 * vars.
 */
const envSchema = z.object({
  NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
  PORT: z.coerce.number().int().positive().default(3001),
  // One Firestore path segment: the namespace root document is `ns/{namespace}`
  // (ADR-0001), so a slash or a reserved `__x__` id would escape it.
  FIRESTORE_NAMESPACE: z
    .string()
    .regex(/^[A-Za-z0-9-]+$/, "must be letters, digits and dashes only")
    .default("dev"),
  // Firestore unless the in-memory twin is asked for explicitly (ADR-0004).
  REPO: repoKindSchema.default("firestore"),
  // Read by `loadCredential`; inline JSON wins over the key-file path.
  FIREBASE_SERVICE_ACCOUNT_JSON: optionalString,
  GOOGLE_APPLICATION_CREDENTIALS: optionalString,
});

export type Config = z.infer<typeof envSchema>;

export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
  const config = envSchema.parse({
    NODE_ENV: env.NODE_ENV,
    PORT: env.PORT,
    FIRESTORE_NAMESPACE: env.FIRESTORE_NAMESPACE,
    REPO: env.REPO,
    FIREBASE_SERVICE_ACCOUNT_JSON: env.FIREBASE_SERVICE_ACCOUNT_JSON,
    GOOGLE_APPLICATION_CREDENTIALS: env.GOOGLE_APPLICATION_CREDENTIALS,
  });

  // The `prod` namespace is only ever used on the server (CODING_STANDARDS,
  // Namespace isolation).
  if (config.FIRESTORE_NAMESPACE === "prod" && config.NODE_ENV !== "production") {
    throw new Error("Refusing to start: FIRESTORE_NAMESPACE=prod requires NODE_ENV=production");
  }

  // In-memory data dies with the process; never in production (ADR-0004).
  if (config.REPO === "memory" && config.NODE_ENV === "production") {
    throw new Error("Refusing to start: REPO=memory is not allowed with NODE_ENV=production");
  }

  return config;
}
/**
 * The one place the API writes diagnostics. Structured JSON lines, so there is
 * never a stray `console.log` in the codebase (CODING_STANDARDS, General).
 */
type Level = "info" | "warn" | "error";

function write(level: Level, msg: string, meta?: Record<string, unknown>): void {
  const entry = {
    level,
    msg,
    time: new Date().toISOString(),
    ...(meta ? { meta } : {}),
  };
  const line = `${JSON.stringify(entry)}\n`;
  if (level === "error") {
    process.stderr.write(line);
  } else {
    process.stdout.write(line);
  }
}

export const logger = {
  info: (msg: string, meta?: Record<string, unknown>) => write("info", msg, meta),
  warn: (msg: string, meta?: Record<string, unknown>) => write("warn", msg, meta),
  error: (msg: string, meta?: Record<string, unknown>) => write("error", msg, meta),
};
import type { Repo, RepoKind } from "@auto-apply/shared";
import type { Config } from "../config.js";
import { loadCredential } from "../firestore/credential.js";
import { openFirestore } from "../firestore/firestore.js";
import { FirestoreRepo } from "./firestore-repo.js";
import { InMemoryRepo } from "./in-memory-repo.js";

export interface Persistence {
  repo: Repo;
  kind: RepoKind;
  close: () => Promise<void>;
}

/**
 * Chooses the `Repo` at boot, with no silent fallback (ADR-0004): the
 * in-memory twin only when `REPO=memory` is set (config already refuses that
 * in production); otherwise Firestore, which needs a valid credential — a
 * missing or malformed one stops the boot.
 */
export function createRepo(config: Config, appName?: string): Persistence {
  if (config.REPO === "memory") {
    return { repo: new InMemoryRepo(), kind: "memory", close: async () => {} };
  }
  const credential = loadCredential(config);
  if (!credential) {
    throw new Error(
      "Refusing to start: no Firestore credential (set GOOGLE_APPLICATION_CREDENTIALS or " +
        "FIREBASE_SERVICE_ACCOUNT_JSON), or set REPO=memory for a non-persistent dev store",
    );
  }
  const handle = openFirestore(credential, appName);
  return {
    repo: new FirestoreRepo(handle.db, config.FIRESTORE_NAMESPACE),
    kind: "firestore",
    close: handle.close,
  };
}

