import express, { type Request, type Response, type NextFunction } from "express";
import cors from "cors";
import {
  errorResponseSchema,
  healthResponseSchema,
  type HealthResponse,
} from "@auto-apply/shared";
import type { Config } from "./config.js";
import type { Persistence } from "./repo/create-repo.js";
import { logger } from "./logger.js";

/**
 * Builds the Express app. Kept separate from `index.ts` so tests can drive it
 * with Supertest without opening a socket. Routes stay thin: later tickets add
 * the run routes and the SSE stream here.
 */
export function createApp(config: Config, persistence: Persistence) {
  const app = express();

  // Behind nginx in production (CLAUDE.md, Deployment).
  app.set("trust proxy", 1);

  // Permissive dev CORS so web (5173) can call api (3001). Tightened to an
  // exact origin with credentials in ticket 15 (D27).
  app.use(cors());

  app.use(express.json({ limit: "100kb" }));

  app.get("/api/health", (_req: Request, res: Response) => {
    const body: HealthResponse = {
      status: "ok",
      service: "auto-apply-api",
      namespace: config.FIRESTORE_NAMESPACE,
      repo: persistence.kind,
      time: new Date().toISOString(),
    };
    res.json(healthResponseSchema.parse(body));
  });

  // Unknown routes get the shared JSON error shape, not Express's HTML default.
  app.use((_req: Request, res: Response) => {
    res.status(404).json(
      errorResponseSchema.parse({
        error: { code: "not_found", message: "Not found" },
      }),
    );
  });

  // Errors return the shared JSON shape, never a stack trace (CODING_STANDARDS).
  app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
    logger.error("unhandled_error", {
      error: err instanceof Error ? err.message : String(err),
    });
    res.status(500).json(
      errorResponseSchema.parse({
        error: { code: "internal", message: "Internal server error" },
      }),
    );
  });

  return app;
}
import { loadConfig } from "./config.js";
import { createApp } from "./app.js";
import { logger } from "./logger.js";
import { createRepo } from "./repo/create-repo.js";

// Env and the Firestore credential are both validated here, once; anything
// invalid stops the boot. The run routes use `persistence.repo` from ticket 05.
const config = loadConfig();
const persistence = createRepo(config);
const app = createApp(config, persistence);

if (persistence.kind === "memory") {
  logger.warn("persistence_in_memory", { reason: "REPO=memory; data is lost on restart" });
}

app.listen(config.PORT, () => {
  logger.info("api_listening", {
    port: config.PORT,
    namespace: config.FIRESTORE_NAMESPACE,
    persistence: persistence.kind,
  });
});
import { z } from "zod";
import { repoKindSchema } from "@auto-apply/shared";

/** An env var that may be absent or blank; blank counts as unset. */
const optionalString = z
  .string()
  .optional()
  .transform((value) => (value ? value : undefined));

/**
 * Environment is parsed once, at startup, and the process fails fast if it is
 * invalid (CODING_STANDARDS, General). Later tickets add the auth, CORS and AI
 * vars.
 */
const envSchema = z.object({
  NODE_ENV: z.enum(["development", "test", "production"]).default("development"),
  PORT: z.coerce.number().int().positive().default(3001),
  // One Firestore path segment: the namespace root document is `ns/{namespace}`
  // (ADR-0001), so a slash or a reserved `__x__` id would escape it.
  FIRESTORE_NAMESPACE: z
    .string()
    .regex(/^[A-Za-z0-9-]+$/, "must be letters, digits and dashes only")
    .default("dev"),
  // Firestore unless the in-memory twin is asked for explicitly (ADR-0004).
  REPO: repoKindSchema.default("firestore"),
  // Read by `loadCredential`; inline JSON wins over the key-file path.
  FIREBASE_SERVICE_ACCOUNT_JSON: optionalString,
  GOOGLE_APPLICATION_CREDENTIALS: optionalString,
});

export type Config = z.infer<typeof envSchema>;

export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
  const config = envSchema.parse({
    NODE_ENV: env.NODE_ENV,
    PORT: env.PORT,
    FIRESTORE_NAMESPACE: env.FIRESTORE_NAMESPACE,
    REPO: env.REPO,
    FIREBASE_SERVICE_ACCOUNT_JSON: env.FIREBASE_SERVICE_ACCOUNT_JSON,
    GOOGLE_APPLICATION_CREDENTIALS: env.GOOGLE_APPLICATION_CREDENTIALS,
  });

  // The `prod` namespace is only ever used on the server (CODING_STANDARDS,
  // Namespace isolation).
  if (config.FIRESTORE_NAMESPACE === "prod" && config.NODE_ENV !== "production") {
    throw new Error("Refusing to start: FIRESTORE_NAMESPACE=prod requires NODE_ENV=production");
  }

  // In-memory data dies with the process; never in production (ADR-0004).
  if (config.REPO === "memory" && config.NODE_ENV === "production") {
    throw new Error("Refusing to start: REPO=memory is not allowed with NODE_ENV=production");
  }

  return config;
}
/**
 * The one place the API writes diagnostics. Structured JSON lines, so there is
 * never a stray `console.log` in the codebase (CODING_STANDARDS, General).
 */
type Level = "info" | "warn" | "error";

function write(level: Level, msg: string, meta?: Record<string, unknown>): void {
  const entry = {
    level,
    msg,
    time: new Date().toISOString(),
    ...(meta ? { meta } : {}),
  };
  const line = `${JSON.stringify(entry)}\n`;
  if (level === "error") {
    process.stderr.write(line);
  } else {
    process.stdout.write(line);
  }
}

export const logger = {
  info: (msg: string, meta?: Record<string, unknown>) => write("info", msg, meta),
  warn: (msg: string, meta?: Record<string, unknown>) => write("warn", msg, meta),
  error: (msg: string, meta?: Record<string, unknown>) => write("error", msg, meta),
};
import type { Repo, RepoKind } from "@auto-apply/shared";
import type { Config } from "../config.js";
import { loadCredential } from "../firestore/credential.js";
import { openFirestore } from "../firestore/firestore.js";
import { FirestoreRepo } from "./firestore-repo.js";
import { InMemoryRepo } from "./in-memory-repo.js";

export interface Persistence {
  repo: Repo;
  kind: RepoKind;
  close: () => Promise<void>;
}

/**
 * Chooses the `Repo` at boot, with no silent fallback (ADR-0004): the
 * in-memory twin only when `REPO=memory` is set (config already refuses that
 * in production); otherwise Firestore, which needs a valid credential — a
 * missing or malformed one stops the boot.
 */
export function createRepo(config: Config, appName?: string): Persistence {
  if (config.REPO === "memory") {
    return { repo: new InMemoryRepo(), kind: "memory", close: async () => {} };
  }
  const credential = loadCredential(config);
  if (!credential) {
    throw new Error(
      "Refusing to start: no Firestore credential (set GOOGLE_APPLICATION_CREDENTIALS or " +
        "FIREBASE_SERVICE_ACCOUNT_JSON), or set REPO=memory for a non-persistent dev store",
    );
  }
  const handle = openFirestore(credential, appName);
  return {
    repo: new FirestoreRepo(handle.db, config.FIRESTORE_NAMESPACE),
    kind: "firestore",
    close: handle.close,
  };
}

