/**
 * The live Run stream (D21): one SSE response per connected browser, fed by the
 * `Repo` subscriptions. Every connect waits for the first `watchRun` callback
 * and the first `watchEvaluations` batch, sends them as one `snapshot`, then
 * forwards later states as `run` / `eval` deltas (full documents, ADR-0003).
 * A terminal Run is followed by `done` and the end of the response. There is no
 * `Last-Event-ID`: a reconnect simply re-snapshots.
 */
import type { Request, Response } from "express";
import {
  doneEventSchema,
  errorEventSchema,
  evalEventSchema,
  isRunActive,
  runEventSchema,
  snapshotEventSchema,
  type Evaluation,
  type EvaluationChange,
  type Repo,
  type Run,
  type SseEventName,
} from "@auto-apply/shared";
import { logger } from "../logger.js";

export function streamRun(
  req: Request,
  res: Response,
  repo: Repo,
  runId: string,
  heartbeatMs: number,
): void {
  res.status(200).set({
    "Content-Type": "text/event-stream",
    "Cache-Control": "no-cache",
    // nginx buffers proxied responses by default; this turns it off per
    // response (CODING_STANDARDS landmine: SSE buffering).
    "X-Accel-Buffering": "no",
    Connection: "keep-alive",
  });
  res.flushHeaders();

  let closed = false;
  // Until the snapshot is sent, callbacks only accumulate the latest state.
  let run: Run | undefined;
  let evaluations: Map<string, Evaluation> | undefined;
  let snapshotSent = false;

  const send = (event: SseEventName, data: unknown) => {
    if (!closed) res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
  };

  const finish = () => {
    if (closed) return;
    closed = true;
    unsubscribeRun();
    unsubscribeEvaluations();
    clearInterval(heartbeat);
    res.end();
  };

  /** A terminal Run ends the stream: the terminal `run` has gone out, so `done`. */
  const endIfTerminal = (latest: Run) => {
    if (isRunActive(latest.status)) return;
    send("done", doneEventSchema.parse({ runId: latest.runId, status: latest.status }));
    finish();
  };

  const trySnapshot = () => {
    if (snapshotSent || !run || !evaluations) return;
    snapshotSent = true;
    send(
      "snapshot",
      snapshotEventSchema.parse({ run, evaluations: [...evaluations.values()] }),
    );
    endIfTerminal(run);
  };

  const onRun = (latest: Run) => {
    run = latest;
    if (!snapshotSent) return trySnapshot();
    send("run", runEventSchema.parse(latest));
    endIfTerminal(latest);
  };

  const onEvaluations = (changes: EvaluationChange[]) => {
    if (!snapshotSent) {
      evaluations ??= new Map();
      for (const { type, evaluation } of changes) {
        if (type === "removed") evaluations.delete(evaluation.jobKey);
        else evaluations.set(evaluation.jobKey, evaluation);
      }
      return trySnapshot();
    }
    for (const { type, evaluation } of changes) {
      // Evaluations are never deleted while a Run streams; nothing to show.
      if (type !== "removed") send("eval", evalEventSchema.parse(evaluation));
    }
  };

  // Never silent (ADR-0003): a subscription failure reaches the browser.
  const onError = (error: Error) => {
    logger.error("run_stream_subscription_error", { runId, error: error.message });
    send(
      "error",
      errorEventSchema.parse({ error: { code: "subscription_error", message: error.message } }),
    );
  };

  const heartbeat = setInterval(() => {
    if (!closed) res.write(": heartbeat\n\n");
  }, heartbeatMs);

  const unsubscribeRun = repo.watchRun(runId, onRun, onError);
  const unsubscribeEvaluations = repo.watchEvaluations(runId, onEvaluations, onError);

  // The browser went away: release the listeners and the timer (landmine:
  // listener leaks).
  req.on("close", finish);
}

